import grpc
from concurrent import futures
import time
import os
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.primitives import padding as sym_padding
from cryptography.hazmat.backends import default_backend
import base64
import json

# Generated protobuf stubs
import token_service_pb2
import token_service_pb2_grpc

SECRET_KEY = os.environ.get('ENCRYPTION_KEY', b'\x00' * 32)
BLOCK_SIZE = 128

class TokenValidationService(token_service_pb2_grpc.TokenValidationServiceServicer):
    """gRPC service for validating encrypted session tokens.
    Deployed on EKS with ALB ingress controller."""

    def __init__(self):
        self.backend = default_backend()
        self.key = SECRET_KEY if isinstance(SECRET_KEY, bytes) else SECRET_KEY.encode('utf-8')[:32]

    def _decrypt_token(self, encrypted_data: bytes):
        """Decrypt AES-CBC encrypted token with PKCS7 padding."""
        if len(encrypted_data) < 32:
            raise ValueError("Token too short")

        iv = encrypted_data[:16]
        ciphertext = encrypted_data[16:]

        if len(ciphertext) % 16 != 0:
            raise ValueError("Invalid ciphertext length")

        cipher = Cipher(algorithms.AES(self.key), modes.CBC(iv), backend=self.backend)
        decryptor = cipher.decryptor()
        padded_plaintext = decryptor.update(ciphertext) + decryptor.finalize()

        # PKCS7 unpadding - vulnerable to padding oracle
        unpadder = sym_padding.PKCS7(BLOCK_SIZE).unpadder()
        plaintext = unpadder.update(padded_plaintext) + unpadder.finalize()

        return plaintext

    def ValidateToken(self, request, context):
        """Validate an encrypted session token.
        Returns specific error codes that leak padding validity."""
        try:
            encrypted_bytes = base64.b64decode(request.encrypted_token)
        except Exception:
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details('Base64 decode failed')
            return token_service_pb2.ValidationResponse(valid=False, error_code=1001)

        try:
            plaintext = self._decrypt_token(encrypted_bytes)
        except ValueError as e:
            error_msg = str(e)
            if "Invalid padding" in error_msg or "invalid padding" in error_msg.lower():
                # VULNERABILITY: Distinct error for padding failure vs other failures
                context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
                context.set_details('Token integrity check failed: padding')
                return token_service_pb2.ValidationResponse(valid=False, error_code=2001)
            else:
                context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
                context.set_details('Token integrity check failed: structure')
                return token_service_pb2.ValidationResponse(valid=False, error_code=2002)
        except Exception as e:
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details('Internal decryption error')
            return token_service_pb2.ValidationResponse(valid=False, error_code=3001)

        # Parse decrypted token
        try:
            token_data = json.loads(plaintext)
            if token_data.get('exp', 0) < time.time():
                return token_service_pb2.ValidationResponse(valid=False, error_code=4001)
            return token_service_pb2.ValidationResponse(
                valid=True, user_id=token_data.get('sub', ''), error_code=0
            )
        except json.JSONDecodeError:
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details('Token payload malformed')
            return token_service_pb2.ValidationResponse(valid=False, error_code=5001)


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    token_service_pb2_grpc.add_TokenValidationServiceServicer_to_server(
        TokenValidationService(), server
    )
    port = os.environ.get('GRPC_PORT', '50051')
    server.add_insecure_port(f'[::]:{port}')
    server.start()
    print(f'TokenValidationService started on port {port}')
    server.wait_for_termination()


if __name__ == '__main__':
    serve()
